using System.Net.Http.Json;
using System.Text.Json;
using SalekhPos.Desktop.Application.Management;
namespace SalekhPos.Desktop.Infrastructure.Management; public sealed class HttpIntegrationManager(HttpClient client) : IIntegrationManager { private static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web); public Task<DesktopIntegrationPage> ConnectionsAsync(Guid org, CancellationToken ct) => GetPage<DesktopIntegrationPage>(org, "connections", ct); public Task<DesktopWebhookPage> WebhooksAsync(Guid org, CancellationToken ct) => GetPage<DesktopWebhookPage>(org, "webhooks", ct); public async Task<DesktopIntegrationConnection> CreateAsync(Guid org, string provider, string name, string endpoint, string secret, Guid op, CancellationToken ct) { ValidateOrg(org); if (op == Guid.Empty || string.IsNullOrWhiteSpace(provider) || string.IsNullOrWhiteSpace(name) || !Uri.TryCreate(endpoint, UriKind.Absolute, out _)) throw new ArgumentException("Integration input is invalid."); using var req = new HttpRequestMessage(HttpMethod.Post, $"api/v1/organizations/{org:D}/integrations/connections") { Content = JsonContent.Create(new { Provider = provider, DisplayName = name, Endpoint = endpoint, SecretReference = secret }, options: Json) }; req.Headers.TryAddWithoutValidation("Idempotency-Key", op.ToString("D")); using var r = await client.SendAsync(req, ct); r.EnsureSuccessStatusCode(); var v = await r.Content.ReadFromJsonAsync<DesktopIntegrationConnection>(Json, ct) ?? throw new InvalidOperationException("Empty integration response."); Validate(v); return v; } private async Task<T> GetPage<T>(Guid org, string suffix, CancellationToken ct) { ValidateOrg(org); using var r = await client.GetAsync($"api/v1/organizations/{org:D}/integrations/{suffix}?pageSize=100", ct); r.EnsureSuccessStatusCode(); return await r.Content.ReadFromJsonAsync<T>(Json, ct) ?? throw new InvalidOperationException("Empty integration response."); } private static void Validate(DesktopIntegrationConnection v) { if (v.Id == Guid.Empty || string.IsNullOrWhiteSpace(v.Provider) || string.IsNullOrWhiteSpace(v.DisplayName) || !Uri.TryCreate(v.Endpoint, UriKind.Absolute, out _)) throw new InvalidOperationException("Integration response is invalid."); } private static void ValidateOrg(Guid org) { if (org == Guid.Empty) throw new ArgumentException("Organization is required."); } }
